-- Testni SQL fragment: razpoloži
CREATE TABLE razpolozi (
  id INT PRIMARY KEY,
  "seStez" TEXT,
  "razdelek2" TEXT,
  opomba TEXT
);
INSERT INTO razpolozi (id, "seStez", "razdelek2", opomba)
VALUES (1, '**poudarek** *zvezdice*', '_podčrtano_', '12 $ / dan');
UPDATE razpolozi SET opomba = 'Vir: https://primer.si/koda' WHERE id = 1;
SELECT id, "seStez", "razdelek2", opomba FROM razpolozi ORDER BY id;

-- Razdelek2: testi za vir
CREATE TABLE viri (
  id INT PRIMARY KEY,
  pot TEXT,
  "HRAŠNA_VREDNOST" TEXT,
  "seStez" TEXT
);
INSERT INTO viri (id, pot, "HRAŠNA_VREDNOST", "seStez")
VALUES (1, 'docs/vir.txt', 'vrednost: 5 $', '`kodica` in **besedilo**');
SELECT id, pot, "HRAŠNA_VREDNOST" FROM viri WHERE pot = 'src/modul.py';
-- Oklepaji: (poudarek _šumniki_)

-- Fragment 3: izpisi za osebo
CREATE TABLE izpisi (
  id INT PRIMARY KEY,
  ime TEXT,
  "razdelek2" TEXT,
  "seStez" TEXT
);
INSERT INTO izpisi (id, ime, "razdelek2", "seStez")
VALUES (1, 'Ana Breznik', 'razdelek 2', 'žetona: 3 $');
UPDATE izpisi SET "seStez" = 'glej https://primer.si/koda in docs/vir.txt';
SELECT ime, "razdelek2", "seStez" FROM izpisi WHERE ime = 'Ana Breznik';
-- Konec: (oklepaji) *zvezdice* `kodica` _podčrtano_
